// ════════════════════════════════════════════════════════════════════════════
// Native oracles (independent of the slice/mirror code paths).
// ════════════════════════════════════════════════════════════════════════════

/// clean-kernel expr/meta.rs mix_hash — VERBATIM.
fn native_mix_hash(h: u64, k: u64) -> u64 {
    const M: u64 = 0xc6a4_a793_5bd1_e995;
    const R: u32 = 47;
    let mut k = k.wrapping_mul(M);
    k ^= k >> R;
    k ^= M;
    let mut h = h ^ k;
    h = h.wrapping_mul(M);
    h
}

/// clean-kernel murmur_hash_64a in the PRODUCTION block form (as-chunks ≡
/// chunks_exact(8) + remainder) — the modules carry the index-loop
/// transcription, so agreement proves [T-murmur-idx] on every tested name.
fn native_murmur_hash_64a(data: &[u8], seed: u64) -> u64 {
    const M: u64 = 0xc6a4_a793_5bd1_e995;
    const R: u32 = 47;
    let len = data.len();
    let mut h: u64 = seed ^ (len as u64).wrapping_mul(M);
    let mut chunks = data.chunks_exact(8);
    for block in &mut chunks {
        let mut k = u64::from_le_bytes(block.try_into().expect("8-byte chunk"));
        k = k.wrapping_mul(M);
        k ^= k >> (R & 63);
        k = k.wrapping_mul(M);
        h ^= k;
        h = h.wrapping_mul(M);
    }
    let tail = chunks.remainder();
    for (i, &b) in tail.iter().enumerate() {
        h ^= (b as u64) << (i.wrapping_mul(8) & 63);
    }
    if !tail.is_empty() {
        h = h.wrapping_mul(M);
    }
    h ^= h >> (R & 63);
    h = h.wrapping_mul(M);
    h ^= h >> (R & 63);
    h
}

/// A decoded Name component, leaf-to-root.
#[derive(Debug, Clone, PartialEq, Eq)]
enum Comp {
    Str(Vec<u8>),
    Num(u64),
}

/// Native `from_string_uncached` with the REAL `split('.')` + REAL
/// `str::parse::<u64>()` (production name.rs:557-565): (leaf-to-root comps,
/// cached_hash). The modules carry the unrolled fold — agreement proves
/// [T-unroll] + [T-parse] on every name (incl. the Num-part "thm.42").
fn native_from_string_uncached(s: &str) -> (Vec<Comp>, u64) {
    let mut comps_root_to_leaf: Vec<Comp> = Vec::new();
    let mut h: u64 = 1723; // anon
    for part in s.split('.') {
        if let Ok(n) = part.parse::<u64>() {
            h = native_mix_hash(h, n);
            comps_root_to_leaf.push(Comp::Num(n));
        } else {
            h = native_mix_hash(h, native_murmur_hash_64a(part.as_bytes(), 11));
            comps_root_to_leaf.push(Comp::Str(part.as_bytes().to_vec()));
        }
    }
    let mut leaf_to_root = comps_root_to_leaf;
    leaf_to_root.reverse();
    (leaf_to_root, h)
}

