const GOLDEN_U: u64 = 0xae572a66f1f7b2e8; // == round-5 pin
const GOLDEN_V: u64 = 0x486e7075aebc6ca6; // == round-5 pin
const GOLDEN_C: u64 = 0x05641f543affb726;
