const GOLDEN_AX_POLYMAX: u64 = 0x9c39ea6e5da28768;
const GOLDEN_THM_POLYMAX: u64 = 0x6742b3cfe3528363;
const GOLDEN_AX_NESTED: u64 = 0x0351fdff76f32065;
const GOLDEN_AX_DUP: u64 = 0xfdb31ca9d0ac3c36;
const GOLDEN_THM_PROP: u64 = 0xae4d449d8cbbbdef;
const GOLDEN_THM_POLY: u64 = 0x04942191c141e64e;
const GOLDEN_DEF_COMMUTE: u64 = 0x228061778109aead;
const GOLDEN_DEF_DEDUP: u64 = 0x6e825e5bdf1f480f;
const GOLDEN_DEF_WRONG: u64 = 0x24c2a446e0f6c7d6;
const GOLDEN_AX_NOTATYPE: u64 = 0x63001da0af393d78;
const GOLDEN_AX_FVAR: u64 = 0xaeeecaae3f64255c;
const GOLDEN_OPQ_POLY: u64 = 0xbf0d948797b2023e;
const GOLDEN_AX_CONSTTY: u64 = 0x57ace85439a0d442;
const GOLDEN_DEF_VALUNDEF: u64 = 0x7a724e6666f41edf;
const GOLDEN_AX_CONSTLVLS: u64 = 0xca04f745a0b64b77;
const GOLDEN_THM42: u64 = 0xdcaef40c027c85c5;
const GOLDEN_ANON: u64 = 1723;

// ── the JIT-side raw Name decode ─────────────────────────────────────────────
// Offsets read VERBATIM off THIS emit's name_anon/name_str_part/name_num_part
// bodies (identical to rounds 4/5): Name = 40 bytes { NameInner @0..32,
// cached_hash @32 }; tag i64 @0 (0=Anon 1=Str 2=Num); Str payload { Arc<Name>
// @8, Arc<str> ptr @16, len @24 }; Num payload FIELD-REORDERED { n u64 @8,
// Arc<Name> @16 }; ArcInner repr(C) { strong @0, weak @8, data @16 } (the
// emitted heap_alloc is 56 bytes = 16 header + 40 Name).

/// Walk a JIT-built Name at `ptr`: returns (leaf-to-root comps, root hash,
/// per-node hashes leaf-to-root). Panics on an unknown tag (fail-loud decode).
unsafe fn decode_jit_name(ptr: *const u8) -> (Vec<Comp>, u64, Vec<u64>) {
    unsafe {
        let mut comps = Vec::new();
        let mut node_hashes = Vec::new();
        let read_u64 = |p: *const u8| -> u64 { (p as *const u64).read_unaligned() };
        let read_ptr = |p: *const u8| -> *const u8 { (p as *const *const u8).read_unaligned() };
        let root_hash = read_u64(ptr.add(32));
        let mut cur = ptr;
        loop {
            let tag = read_u64(cur);
            node_hashes.push(read_u64(cur.add(32)));
            match tag {
                0 => break,
                1 => {
                    let parent_inner = read_ptr(cur.add(8));
                    let s_inner = read_ptr(cur.add(16));
                    let s_len = read_u64(cur.add(24)) as usize;
                    let bytes = std::slice::from_raw_parts(s_inner.add(16), s_len).to_vec();
                    comps.push(Comp::Str(bytes));
                    cur = parent_inner.add(16);
                }
                2 => {
                    let n = read_u64(cur.add(8));
                    let parent_inner = read_ptr(cur.add(16));
                    comps.push(Comp::Num(n));
                    cur = parent_inner.add(16);
                }
                t => panic!("decode_jit_name: unknown NameInner tag {t} (layout drift?)"),
            }
        }
        (comps, root_hash, node_hashes)
    }
}

/// Recompute the production hash chain from decoded comps (leaf-to-root):
/// per-node hashes leaf-to-root INCLUDING the final Anon node (1723).
fn recompute_hash_chain(comps: &[Comp]) -> Vec<u64> {
    let mut fwd = vec![1723u64];
    for c in comps.iter().rev() {
        let prev = *fwd.last().unwrap();
        let h = match c {
            Comp::Str(b) => native_mix_hash(prev, native_murmur_hash_64a(b, 11)),
            Comp::Num(n) => native_mix_hash(prev, *n),
        };
        fwd.push(h);
    }
    fwd.reverse();
    fwd
}

/// SAFE walk of a HOST-built (mirror) Name: (leaf-to-root comps, root hash).
fn native_name_comps(n: &rn::Name) -> (Vec<Comp>, u64) {
    let mut comps = Vec::new();
    let mut cur = n;
    loop {
        match &cur.inner {
            rn::NameInner::Anon => break,
            rn::NameInner::Str(p, s) => {
                comps.push(Comp::Str(s.as_bytes().to_vec()));
                cur = &**p;
            }
            rn::NameInner::Num(p, v) => {
                comps.push(Comp::Num(*v));
                cur = &**p;
            }
        }
    }
    (comps, n.cached_hash)
}

// ════════════════════════════════════════════════════════════════════════════
// The asymmetric deep comparators: native side walked SAFELY via mirror types
// (host-built memory), JIT side Names decoded RAW at the documented offsets
// with the per-node hash chain REVALIDATED on every comparison (fail-loud on
// any layout drift). Meta words compared bit-exact at every node.
// ════════════════════════════════════════════════════════════════════════════

/// Compare a native (host-built) Name against a JIT (module-built) Name.
fn name_eq_nj(native: &rn::Name, jit: &rn::Name) -> bool {
    let (ncomps, nhash) = native_name_comps(native);
    let (jcomps, jhash, jchain) = unsafe { decode_jit_name(jit as *const rn::Name as *const u8) };
    // Chain revalidation: the JIT name's per-node cached_hash values must be
    // the production recompute of its decoded comps — ALWAYS, not just when
    // the comparison is expected to succeed.
    let expect_chain = recompute_hash_chain(&jcomps);
    assert_eq!(
        jchain, expect_chain,
        "JIT Name per-node hash chain != production recompute (layout drift or hash bug?)"
    );
    ncomps == jcomps && nhash == jhash
}

fn level_eq_nj(native: &rn::Level, jit: &rn::Level) -> bool {
    match (native, jit) {
        (rn::Level::Zero, rn::Level::Zero) => true,
        (rn::Level::Succ(a), rn::Level::Succ(b)) => level_eq_nj(a, b),
        (rn::Level::Max(a1, b1), rn::Level::Max(a2, b2)) => {
            level_eq_nj(a1, a2) && level_eq_nj(b1, b2)
        }
        (rn::Level::IMax(a1, b1), rn::Level::IMax(a2, b2)) => {
            level_eq_nj(a1, a2) && level_eq_nj(b1, b2)
        }
        (rn::Level::Param(a), rn::Level::Param(b)) => name_eq_nj(a, b),
        _ => false,
    }
}

fn levels_eq_nj(native: &[rn::Level], jit: &[rn::Level]) -> bool {
    if native.len() != jit.len() {
        return false;
    }
    native
        .iter()
        .zip(jit.iter())
        .all(|(a, b)| level_eq_nj(a, b))
}

/// Deep native==JIT comparison: meta word BIT-IDENTICAL at every node
/// (routes through the FIXED Const arm's name_hash+levels_hash chain and the
/// Sort arm's Level hash chain — both now carrying REAL Name cached_hash),
/// then structural with production-name comparison at every Name site.
fn deep_eq_nj(native: &rn::Expr, jit: &rn::Expr) -> bool {
    if native.meta.raw() != jit.meta.raw() {
        return false;
    }
    match (&native.kind, &jit.kind) {
        (rn::ExprKind::BVar(x), rn::ExprKind::BVar(y)) => x == y,
        (rn::ExprKind::FVar(x), rn::ExprKind::FVar(y)) => x == y,
        (rn::ExprKind::Lit(x), rn::ExprKind::Lit(y)) => x == y,
        (rn::ExprKind::Sort(x), rn::ExprKind::Sort(y)) => level_eq_nj(x, y),
        (rn::ExprKind::Const(n1, l1), rn::ExprKind::Const(n2, l2)) => {
            name_eq_nj(n1, n2) && levels_eq_nj(l1, l2)
        }
        (rn::ExprKind::App(f1, a1), rn::ExprKind::App(f2, a2)) => {
            deep_eq_nj(f1, f2) && deep_eq_nj(a1, a2)
        }
        (rn::ExprKind::Lam(b1, t1, y1), rn::ExprKind::Lam(b2, t2, y2)) => {
            b1 == b2 && deep_eq_nj(t1, t2) && deep_eq_nj(y1, y2)
        }
        (rn::ExprKind::Pi(b1, t1, y1), rn::ExprKind::Pi(b2, t2, y2)) => {
            b1 == b2 && deep_eq_nj(t1, t2) && deep_eq_nj(y1, y2)
        }
        (rn::ExprKind::Let(n1, t1, v1, y1, d1), rn::ExprKind::Let(n2, t2, v2, y2, d2)) => {
            name_eq_nj(n1, n2)
                && deep_eq_nj(t1, t2)
                && deep_eq_nj(v1, v2)
                && deep_eq_nj(y1, y2)
                && d1 == d2
        }
        (rn::ExprKind::Proj(n1, i1, e1), rn::ExprKind::Proj(n2, i2, e2)) => {
            name_eq_nj(n1, n2) && i1 == i2 && deep_eq_nj(e1, e2)
        }
        (rn::ExprKind::MData(m1, e1), rn::ExprKind::MData(m2, e2)) => {
            m1 == m2 && deep_eq_nj(e1, e2)
        }
        _ => false,
    }
}

fn type_error_disc(e: &rn::TypeError) -> u8 {
    match e {
        rn::TypeError::UnboundVariable(_) => 0,
        rn::TypeError::UnknownConst(_) => 1,
        rn::TypeError::TypeMismatch { .. } => 2,
        rn::TypeError::NotAPi { .. } => 3,
        rn::TypeError::ExpectedSort { .. } => 4,
        rn::TypeError::SortDepthExceeded { .. } => 5,
        rn::TypeError::Unsupported => 6,
    }
}

fn env_error_disc(e: &rn::EnvError) -> u8 {
    match e {
        rn::EnvError::TypeCheckFailed { .. } => 0,
        rn::EnvError::DuplicateLevelParam { .. } => 1,
        rn::EnvError::TheoremTypeNotProp { .. } => 2,
        rn::EnvError::ContainsFreeVar { .. } => 3,
        rn::EnvError::ContainsMetavar { .. } => 4,
        rn::EnvError::UndefinedLevelParam { .. } => 5,
    }
}

/// Payload-deep agreement between the native gate error and the JIT gate
/// error: variant + REAL-Name payloads (raw-decoded + chain-revalidated) +
/// universe payloads structural + TypeMismatch/ExpectedSort/NotAPi expr
/// payloads meta-bit-identical at every node. DEEPER than the landed T1
/// comparator: ExpectedSort's ty is now deep-compared too (it carries the
/// JIT-built Const("Nat") through the FIXED Const meta arm).
fn env_error_agrees_nj(n: &rn::EnvError, j: &rn::EnvError) -> bool {
    if env_error_disc(n) != env_error_disc(j) {
        return false;
    }
    match (n, j) {
        (
            rn::EnvError::TypeCheckFailed {
                name: n1,
                source: s1,
            },
            rn::EnvError::TypeCheckFailed {
                name: n2,
                source: s2,
            },
        ) => {
            name_eq_nj(n1, n2)
                && type_error_disc(s1) == type_error_disc(s2)
                && match (s1, s2) {
                    (
                        rn::TypeError::TypeMismatch {
                            expected: e1,
                            inferred: i1,
                        },
                        rn::TypeError::TypeMismatch {
                            expected: e2,
                            inferred: i2,
                        },
                    ) => deep_eq_nj(e1, e2) && deep_eq_nj(i1, i2),
                    (
                        rn::TypeError::ExpectedSort { ty: t1 },
                        rn::TypeError::ExpectedSort { ty: t2 },
                    ) => deep_eq_nj(t1, t2),
                    (rn::TypeError::NotAPi { ty: t1 }, rn::TypeError::NotAPi { ty: t2 }) => {
                        deep_eq_nj(t1, t2)
                    }
                    (rn::TypeError::UnknownConst(c1), rn::TypeError::UnknownConst(c2)) => {
                        name_eq_nj(c1, c2)
                    }
                    _ => true,
                }
        }
        (
            rn::EnvError::DuplicateLevelParam {
                name: n1,
                param: p1,
            },
            rn::EnvError::DuplicateLevelParam {
                name: n2,
                param: p2,
            },
        ) => name_eq_nj(n1, n2) && name_eq_nj(p1, p2),
        (
            rn::EnvError::TheoremTypeNotProp { name: n1, sort: s1 },
            rn::EnvError::TheoremTypeNotProp { name: n2, sort: s2 },
        ) => name_eq_nj(n1, n2) && level_eq_nj(s1, s2),
        (
            rn::EnvError::ContainsFreeVar { name: n1 },
            rn::EnvError::ContainsFreeVar { name: n2 },
        ) => name_eq_nj(n1, n2),
        (
            rn::EnvError::ContainsMetavar { name: n1 },
            rn::EnvError::ContainsMetavar { name: n2 },
        ) => name_eq_nj(n1, n2),
        (
            rn::EnvError::UndefinedLevelParam {
                name: n1,
                param: p1,
            },
            rn::EnvError::UndefinedLevelParam {
                name: n2,
                param: p2,
            },
        ) => name_eq_nj(n1, n2) && name_eq_nj(p1, p2),
        _ => false,
    }
}

// ── drivers ──────────────────────────────────────────────────────────────────

type DnGateFn = extern "C" fn(*mut Result<(), rn::EnvError>, *mut rn::Expr, u64);
type DnProbeFn = extern "C" fn(*mut rn::Name, u64);

fn jit_gate(f: DnGateFn, case: u64) -> (Result<(), rn::EnvError>, rn::Expr) {
    let mut res_slot = std::mem::MaybeUninit::<Result<(), rn::EnvError>>::uninit();
    let mut ty_slot = std::mem::MaybeUninit::<rn::Expr>::uninit();
    unsafe {
        f(res_slot.as_mut_ptr(), ty_slot.as_mut_ptr(), case);
        (res_slot.assume_init(), ty_slot.assume_init())
    }
}

/// The native oracle — the mirror gate over mirror-built inputs (the same
/// construction path the root body performs, running as host-compiled Rust).
fn native_gate(case: u64) -> (Result<(), rn::EnvError>, rn::Expr) {
    let env = rn::build_env();
    let ctors: Vec<(rn::Name, u32)> = Vec::new();
    let verifier = rn::Verifier {
        env: &env,
        ctors: &ctors,
    };
    let decl = rn::build_decl_case(case);
    let ty: rn::Expr = match &decl {
        rn::Declaration::Definition { type_, .. } => type_.as_ref().clone(),
        rn::Declaration::Axiom { type_, .. } => type_.as_ref().clone(),
        rn::Declaration::Theorem { type_, .. } => type_.as_ref().clone(),
        rn::Declaration::Opaque { type_, .. } => type_.as_ref().clone(),
    };
    (verifier.check_decl_readonly(&decl), ty)
}

// Hand-built-name helper for pinned expectations (mirror machinery — the same
// fold production from_string performs).
fn hn1(s: &str) -> rn::Name {
    rn::fold_step(rn::name_anon(), s)
}

extern "C" fn read_u64_for_stack_arg_regression(value: *const u64) -> u64 {
    unsafe { *value }
}

#[test]
fn aarch64_external_call_reads_exact_stack_slot_address() {
    const MODULE: &str = r#"
module "stack_arg_address"
target "aarch64-apple-darwin" 8 little
functy.0 = (ptr) -> (u64)
functy.1 = (ptr) -> (u64)
fn @stack_arg_address(functy.0) {
bb0(%0: ptr):
    %1 = alloca i64, align 8
    %2 = alloca i64, align 8
    store ptr %0, ptr %1
    %3 = load ptr, ptr %1
    %4 = load i32, ptr %3
    %5 = sext i32 %4 to i64
    store i64 %5, ptr %2
    %6 = call @func.1(%2)
    ret %6
}
fn @read_u64_for_stack_arg_regression(functy.1) {
}
"#;
    let externs = HashMap::from([(
        "read_u64_for_stack_arg_regression".to_string(),
        read_u64_for_stack_arg_regression as *const u8,
    )]);
    let buffer = jit_module(MODULE, "stack argument address regression", &externs);
    let run: extern "C" fn(*const u32) -> u64 =
        unsafe { std::mem::transmute(bind(&buffer, "stack_arg_address")) };
    let tagged = [0_u32, 1_u32];
    assert_eq!(
        run(tagged.as_ptr()),
        0,
        "external call must receive the address of the fully overwritten i64 stack slot"
    );
}

#[test]
fn aarch64_sext_i32_to_i64_store_overwrites_full_word() {
    const MODULE: &str = r#"
module "sext_store_full_word"
target "aarch64-apple-darwin" 8 little
functy.0 = () -> (u64)
fn @sext_store_full_word(functy.0) {
bb0:
    %0 = alloca i64, align 8
    %1 = const u64 4294967296
    store u64 %1, ptr %0
    %2 = const i32 0
    %3 = sext i32 %2 to i64
    store i64 %3, ptr %0
    %4 = load u64, ptr %0
    ret %4
}
"#;
    let buffer = jit_module(MODULE, "sext-store full-word regression", &HashMap::new());
    let run: extern "C" fn() -> u64 =
        unsafe { std::mem::transmute(bind(&buffer, "sext_store_full_word")) };
    assert_eq!(run(), 0, "i64 store of sext(i32 0) must clear all 64 bits");
}

// ════════════════════════════════════════════════════════════════════════════
// TEST 1 — module sanity: both fixtures parse + validate 0; the full gate,
// the full production-Level universe machinery AND the full real-Name
// machinery are genuinely IN-MODULE (bodied); the composition edges RUN (the
// gate calls §4/§5/§6/§7 AND name_eq for §2; level_eq calls Level::is_def_eq;
// is_norm_lt calls the production Name-Ord transcription; compute_meta's
// FIXED Const arm calls hash_name AND hash_levels).
// ════════════════════════════════════════════════════════════════════════════

#[test]
fn dn_module_sanity_and_inmodule_surface() {
    for (text, what) in [
        (DN_MAIN_TRUST_IR, "decl_gate_realnames_root closure"),
        (DN_PROBE_TRUST_IR, "declnames_probe_root closure"),
    ] {
        let module = parse_and_validate(text, what);
        let bodied = |sym: &str| {
            module
                .functions
                .iter()
                .find(|f| f.name == sym)
                .map(|f| !f.blocks.is_empty())
                .unwrap_or(false)
        };
        // The real-Name machinery must be in-module in BOTH fixtures.
        for sym in [
            "name_anon",
            "name_str_part",
            "name_num_part",
            "murmur_hash_64a_idx",
            "mix_hash",
            "parse_u64_ascii",
            "fold_step",
            "hash_name",
            "hash_levels",
            "build_decl_case",
            "build_env",
            "nm1",
            "nm2",
            "ExprKind__compute_meta",
        ] {
            assert!(
                bodied(sym),
                "`{sym}` must be lowered in-module (bodied) in {what}"
            );
        }
    }

    // Main fixture: the full gate + pillars + Level machinery + Name
    // comparison machinery bodied.
    let module = parse_and_validate(DN_MAIN_TRUST_IR, "decl_gate_realnames_root closure");
    let bodied = |sym: &str| {
        module
            .functions
            .iter()
            .find(|f| f.name == sym)
            .map(|f| !f.blocks.is_empty())
            .unwrap_or(false)
    };
    for sym in [
        "Verifier____env___check_decl_readonly",
        "Verifier____env___infer_sort",
        "Verifier____env___infer_sort_inner",
        "Verifier____env___check_type",
        "Verifier____env___infer_type",
        "Verifier____env___infer_type_core",
        "Verifier____env___whnf_impl",
        "Verifier____env___whnf_inner",
        "Verifier____env___is_def_eq",
        "Verifier____env___def_eq_inner",
        "Verifier____env___structural_eq",
        "Verifier____env___level_eq",
        "Verifier____env___unfold_const",
        "Expr__instantiate",
        "Expr__lift_at",
        "find_undef_level_param",
        "find_undef_level_param_in_level",
        // the full-universe pillar, in-module:
        "Level__is_def_eq",
        "Level__normalize",
        "Level__normalize_impl",
        "Level__normalize_max",
        "Level__push_max_args",
        "Level__is_norm_lt",
        "Level__dedup_max_args",
        "Level__subsume_max_args",
        "Level__mk_max_from_args",
        "Level__is_geq_core",
        "Level__is_geq_leaf",
        "Level__imax",
        "Level__max",
        "Level__succ",
        "Level__is_zero",
        "Level__is_nonzero",
        "Level__has_params",
        "Level__get_offset",
        "Level__add_offset",
        "_Level_as_std__cmp__PartialEq___eq",
        "_Level_as_std__hash__Hash___hash",
        // the real-Name comparison machinery, in-module:
        "name_eq",
        "str_bytes_eq",
        "name_cmp_is_lt",
        "str_bytes_cmp",
    ] {
        assert!(bodied(sym), "`{sym}` must be lowered in-module (bodied)");
    }

    // ── CONFIRM the composition edges are RUNNING (not bypassed), by IR text.
    //    Function indices are resolved dynamically from the parsed module
    //    (module.functions order == text order; calls are `@func.N(`). ──
    let idx_of = |sym: &str| -> usize {
        module
            .functions
            .iter()
            .position(|f| f.name == sym)
            .unwrap_or_else(|| panic!("`{sym}` not in module"))
    };
    let body_of = |sym: &str| -> &str {
        let start = DN_MAIN_TRUST_IR
            .find(&format!("fn @{sym}("))
            .unwrap_or_else(|| panic!("`{sym}` header present in IR text"));
        let after = &DN_MAIN_TRUST_IR[start + 1..];
        let end = after
            .find("\nfn @")
            .map(|i| start + 1 + i)
            .unwrap_or(DN_MAIN_TRUST_IR.len());
        &DN_MAIN_TRUST_IR[start..end]
    };
    let edge = |caller: &str, callee: &str| {
        let b = body_of(caller);
        let i = idx_of(callee);
        assert!(
            b.contains(&format!("@func.{i}(")),
            "`{caller}` must Call @func.{i} = `{callee}` — the composition edge must RUN"
        );
    };
    // gate -> §2 (REAL name_eq!) + §4 + §5 + §6 + §7.
    edge("Verifier____env___check_decl_readonly", "name_eq");
    edge(
        "Verifier____env___check_decl_readonly",
        "find_undef_level_param",
    );
    edge(
        "Verifier____env___check_decl_readonly",
        "Verifier____env___infer_sort",
    );
    edge("Verifier____env___check_decl_readonly", "Level__is_zero");
    edge(
        "Verifier____env___check_decl_readonly",
        "Verifier____env___check_type",
    );
    // THE UNIVERSE INTEGRATION: level_eq -> the full Level::is_def_eq.
    edge("Verifier____env___level_eq", "Level__is_def_eq");
    // §5 composes inference + reduction + the FULL imax.
    edge(
        "Verifier____env___infer_sort_inner",
        "Verifier____env___infer_type_core",
    );
    edge(
        "Verifier____env___infer_sort_inner",
        "Verifier____env___whnf_impl",
    );
    edge("Verifier____env___infer_sort_inner", "Level__imax");
    // EVERY Name comparison is the production name_eq / name Ord:
    edge("Verifier____env___unfold_const", "name_eq");
    edge("find_undef_level_param_in_level", "name_eq");
    edge("Verifier____env___structural_eq", "name_eq");
    edge("_Level_as_std__cmp__PartialEq___eq", "name_eq");
    edge("Level__is_norm_lt", "name_cmp_is_lt");
    edge("name_cmp_is_lt", "str_bytes_cmp");
    edge("name_eq", "str_bytes_eq");
    // The FIXED Const meta arm: name hash AND levels hash both mixed.
    edge("ExprKind__compute_meta", "hash_name");
    edge("ExprKind__compute_meta", "hash_levels");
    // The name construction chain.
    edge("name_str_part", "murmur_hash_64a_idx");
    edge("name_str_part", "mix_hash");
    edge("fold_step", "parse_u64_ascii");
    edge("fold_step", "name_num_part");
    edge("fold_step", "name_str_part");
}

// ════════════════════════════════════════════════════════════════════════════
// TEST 2 — the NAME PROBE: every Name the scenarios construct, built by JIT
// machine code from literal parts, decoded raw and pinned BIT-IDENTICAL to
// the real clean-kernel goldens (21/21), with the per-node hash chain
// revalidated and the Num decode arm LIVE ("thm.42"). Armed controls: a
// corrupted golden and a crossed-name expectation both REJECT.
// ════════════════════════════════════════════════════════════════════════════

#[test]
fn dn_probe_names_bitidentical_to_kernel_goldens() {
    let buffer = run_with_watchdog("JIT compile declnames_probe_root", move || {
        jit_module(
            DN_PROBE_TRUST_IR,
            "declnames_probe_root closure",
            &dn_externs(),
        )
    });
    let probe: DnProbeFn = unsafe { std::mem::transmute(bind(&buffer, "declnames_probe_root")) };

    let run_probe = |idx: u64| -> rn::Name {
        let mut slot = std::mem::MaybeUninit::<rn::Name>::uninit();
        unsafe {
            probe(slot.as_mut_ptr(), idx);
            slot.assume_init()
        }
    };

    let expectations: [(u64, &str, u64); 21] = [
        (0, "ax.polymax", GOLDEN_AX_POLYMAX),
        (1, "thm.polymax", GOLDEN_THM_POLYMAX),
        (2, "ax.nested", GOLDEN_AX_NESTED),
        (3, "ax.dup", GOLDEN_AX_DUP),
        (4, "thm.prop", GOLDEN_THM_PROP),
        (5, "thm.poly", GOLDEN_THM_POLY),
        (6, "def.commute", GOLDEN_DEF_COMMUTE),
        (7, "def.dedup", GOLDEN_DEF_DEDUP),
        (8, "def.wrong", GOLDEN_DEF_WRONG),
        (9, "ax.notatype", GOLDEN_AX_NOTATYPE),
        (10, "ax.fvar", GOLDEN_AX_FVAR),
        (11, "opq.poly", GOLDEN_OPQ_POLY),
        (12, "ax.constty", GOLDEN_AX_CONSTTY),
        (13, "def.valundef", GOLDEN_DEF_VALUNDEF),
        (14, "ax.constlvls", GOLDEN_AX_CONSTLVLS),
        (15, "thm.42", GOLDEN_THM42),
        (16, "u", GOLDEN_U),
        (17, "v", GOLDEN_V),
        (18, "c", GOLDEN_C),
        (19, "Nat", GOLDEN_NAT),
        (20, "String", GOLDEN_STRING),
    ];

    for (idx, s, golden) in expectations {
        let jit_name = run_probe(idx);
        let (jcomps, jhash, jchain) =
            unsafe { decode_jit_name(&jit_name as *const rn::Name as *const u8) };
        // 1. The JIT-built cached_hash is BIT-IDENTICAL to the real
        //    clean-kernel golden for `Name::from_string(s)`.
        assert_eq!(
            jhash, golden,
            "probe {idx} `{s}`: JIT cached_hash {jhash:#018x} != clean-kernel golden {golden:#018x}"
        );
        // 2. The decoded components equal the REAL split('.')+parse fold.
        let (ecomps, ehash) = native_from_string_uncached(s);
        assert_eq!(jcomps, ecomps, "probe {idx} `{s}`: decoded comps mismatch");
        assert_eq!(
            ehash, golden,
            "oracle self-check: from_string_uncached(`{s}`) != golden"
        );
        // 3. Per-node chain revalidation (every intermediate cached_hash).
        let expect_chain = recompute_hash_chain(&jcomps);
        assert_eq!(
            jchain, expect_chain,
            "probe {idx} `{s}`: per-node hash chain mismatch"
        );
    }

    // The Num decode arm is LIVE: "thm.42" must decode through tag 2 with the
    // field-reordered payload (n @+8, parent @+16).
    let t42 = run_probe(15);
    let (comps, _, _) = unsafe { decode_jit_name(&t42 as *const rn::Name as *const u8) };
    assert_eq!(
        comps,
        vec![Comp::Num(42), Comp::Str(b"thm".to_vec())],
        "probe 15 must decode leaf-to-root as [Num(42), Str(thm)] — the Num arm must be LIVE"
    );

    // Out-of-range probe: anon (hash 1723) — the never-asked guard.
    let anon = run_probe(21);
    assert_eq!(
        anon.cached_hash, GOLDEN_ANON,
        "probe 21 must be the anon guard"
    );

    // ── ARMED CONTROL 1: a corrupted golden must REJECT (proves the pin is
    //    sensitive to a single bit of the constant). ──
    let u_name = run_probe(16);
    let (_, uhash, _) = unsafe { decode_jit_name(&u_name as *const rn::Name as *const u8) };
    assert_ne!(
        uhash,
        GOLDEN_U.wrapping_add(1),
        "ARMED CONTROL FAILED: the corrupted golden (GOLDEN_U+1) matched — the pin is vacuous"
    );

    // ── ARMED CONTROL 2: a crossed-name expectation must REJECT (the decoded
    //    dup-param name `u` must NOT satisfy the expectation for `v`). ──
    let (ucomps, uh, _) = unsafe { decode_jit_name(&u_name as *const rn::Name as *const u8) };
    let (vcomps, vh) = native_from_string_uncached("v");
    assert!(
        !(ucomps == vcomps && uh == vh),
        "ARMED CONTROL FAILED: the crossed-name expectation (`v` for the JIT `u`) matched"
    );

    drop(buffer);
}

// ════════════════════════════════════════════════════════════════════════════
// TEST 3 — the FULL decl-gate differential over REAL Names: all 16 in-module
// scenarios, native == JIT on accept/reject AND on every error payload
// (REAL-Name payloads raw-decoded + chain-revalidated; universe payloads
// structural with production-name comparison; expr payloads meta-bit-
// identical at every node), the declared-type meta words bit-identical
// native == JIT for every case (the compute_meta Sort/Const chains over real
// Name hashes — incl. the FIXED Const arm on empty AND non-empty levels),
// the pinned universe witnesses, and the fail-loud negative controls.
// ════════════════════════════════════════════════════════════════════════════

#[test]
fn dn_decl_gate_full_differential_realnames() {
    let buffer = run_with_watchdog("JIT compile decl_gate_realnames_root", move || {
        jit_module(
            DN_MAIN_TRUST_IR,
            "decl_gate_realnames_root closure",
            &dn_externs(),
        )
    });
    let gate: DnGateFn = unsafe { std::mem::transmute(bind(&buffer, "decl_gate_realnames_root")) };

    let labels: [&str; 16] = [
        "ACCEPT ax.polymax{u,v} : Sort(max u v)",
        "REJECT §6 thm.polymax{u,v} : Sort(max u v) [sort=succ(max u v) not Prop]",
        "REJECT §4 ax.nested{u} : Sort(max u (imax v u)) [undef v inside IMax]",
        "REJECT §2 ax.dup{u,v,u} [duplicate param u — REAL name_eq]",
        "ACCEPT thm.prop : (∀α:Prop. α→α) := λλ#0 [imax(_,0)=0 edge]",
        "REJECT §6 thm.poly{u} : (∀α:Sort u. α→α) [sort=IMax(succ u,u) not Prop]",
        "ACCEPT def.commute{u,v} : Sort(succ(max v u)) := Sort(max u v) [§7 Max commutativity]",
        "ACCEPT def.dedup{u,v} : Sort(max(succ u)(succ v)) := ∀α:Sort u.∀x:α.Sort v [imax->Max + dedup]",
        "REJECT §7 def.wrong{u,v} : Sort(max u v) := Sort(max v u) [wrong universe]",
        "REJECT §5 ax.notatype : Nat(7) [ExpectedSort — payload Const(Nat)]",
        "REJECT §3 ax.fvar : FVar(5) [ContainsFreeVar]",
        "ACCEPT opq.poly{u} : Sort(succ u) := Sort(u)",
        "ACCEPT ax.constty : Const(c) [env unfold name_eq HIT + infer_sort Pi arm]",
        "REJECT §4 def.valundef{v} := Sort(u) [undef u in value]",
        "REJECT §4 ax.constlvls{u} : Const(c,[imax(v,u)]) [undef v inside Const LEVELS]",
        "REJECT §2 thm.42{u,u} [duplicate param u — decl name carries a REAL Num part]",
    ];

    let mut accepts = 0usize;
    let mut rejects = 0usize;
    let mut jit_results: Vec<Result<(), rn::EnvError>> = Vec::new();
    for case in 0u64..16 {
        let label = labels[case as usize];
        let (native, nty) = native_gate(case);
        let (jit, jty) = jit_gate(gate, case);
        // The declared TYPE built by JIT machine code (real Names, real
        // levels) must be meta-bit-identical to the native mirror build at
        // every node — the compute_meta differential on the INPUT side.
        assert!(
            deep_eq_nj(&nty, &jty),
            "case {case} `{label}`: JIT-built declared type must be meta-bit-identical to native; \
             native_meta={:#018x}, jit_meta={:#018x}, native_kind={:?}, jit_kind={:?}",
            nty.meta.raw(),
            jty.meta.raw(),
            nty.kind,
            jty.kind,
        );
        match (&native, &jit) {
            (Ok(()), Ok(())) => accepts += 1,
            (Err(ne), Err(je)) => {
                assert!(
                    env_error_agrees_nj(ne, je),
                    "decl gate JIT disagrees with native on `{label}` (both Err, payloads differ):\n  native = {ne:?}\n  jit    = {je:?}"
                );
                rejects += 1;
            }
            _ => panic!(
                "decl gate JIT vs native ACCEPT/REJECT disagreement on `{label}`:\n  native = {native:?}\n  jit    = {jit:?}"
            ),
        }
        jit_results.push(jit);
    }
    assert_eq!(
        accepts, 6,
        "expected exactly 6 ACCEPTs (cases 0,4,6,7,11,12)"
    );
    assert_eq!(rejects, 10, "expected exactly 10 REJECTs");

    // ── PINNED payload checks: the JIT-BUILT universe payloads, deref'd. ──
    // Case 5: sort must be EXACTLY IMax(Succ(Param u), Param u) — a real IMax
    // node built by the JIT's full smart-imax, its Param names decoding to the
    // clean-kernel `u` golden.
    let expected_imax = rn::Level::IMax(
        Arc::new(rn::Level::Succ(Arc::new(rn::Level::Param(hn1("u"))))),
        Arc::new(rn::Level::Param(hn1("u"))),
    );
    let jit5_sort = match &jit_results[5] {
        Err(rn::EnvError::TheoremTypeNotProp { sort, .. }) => sort.clone(),
        other => panic!("case 5 must be TheoremTypeNotProp, got {other:?}"),
    };
    assert!(
        level_eq_nj(&expected_imax, &jit5_sort),
        "case 5: JIT-built sort payload must be IMax(succ u, u) with the REAL `u`; got {jit5_sort:?}"
    );
    match &jit5_sort {
        rn::Level::IMax(_, b) => match &**b {
            rn::Level::Param(n) => {
                let (_, h, _) = unsafe { decode_jit_name(n as *const rn::Name as *const u8) };
                assert_eq!(
                    h, GOLDEN_U,
                    "case 5: the IMax Param name must be the kernel `u` golden"
                );
            }
            other => panic!("case 5: IMax right arm must be Param(u), got {other:?}"),
        },
        _ => unreachable!(),
    }
    // Case 1: sort must be Succ(Max(u,v)) with real u/v names.
    let expected_succmax = rn::Level::Succ(Arc::new(rn::Level::Max(
        Arc::new(rn::Level::Param(hn1("u"))),
        Arc::new(rn::Level::Param(hn1("v"))),
    )));
    match &jit_results[1] {
        Err(rn::EnvError::TheoremTypeNotProp { sort, .. }) => {
            assert!(
                level_eq_nj(&expected_succmax, sort),
                "case 1: JIT-built sort payload must be succ(max u v); got {sort:?}"
            );
        }
        other => panic!("case 1 must be TheoremTypeNotProp, got {other:?}"),
    }
    // Case 8: the TypeMismatch payloads must be meta-bit-identical (checked in
    // the loop) and the JIT-CONSTRUCTED inferred type must be the
    // wrong-universe witness Sort(succ(..)).
    let (j8_exp, j8_inf) = match &jit_results[8] {
        Err(rn::EnvError::TypeCheckFailed {
            source: rn::TypeError::TypeMismatch { expected, inferred },
            ..
        }) => (expected.clone(), inferred.clone()),
        other => panic!("case 8 JIT must be TypeMismatch, got {other:?}"),
    };
    assert!(
        matches!(&j8_inf.kind, rn::ExprKind::Sort(rn::Level::Succ(_))),
        "case 8: the JIT-built inferred type must be Sort(succ(..)) — the wrong-universe witness"
    );
    // Case 9: ExpectedSort payload = the JIT-built Const("Nat") — the B11 name
    // built from literal parts INSIDE inference, pinned to the kernel golden.
    match &jit_results[9] {
        Err(rn::EnvError::TypeCheckFailed {
            source: rn::TypeError::ExpectedSort { ty },
            ..
        }) => match &ty.kind {
            rn::ExprKind::Const(n, levels) => {
                assert!(levels.is_empty(), "case 9: Const(Nat) must carry no levels");
                let (comps, h, _) = unsafe { decode_jit_name(n as *const rn::Name as *const u8) };
                assert_eq!(
                    h, GOLDEN_NAT,
                    "case 9: the Lit-rule type name must be the kernel `Nat` golden"
                );
                assert_eq!(comps, vec![Comp::Str(b"Nat".to_vec())]);
            }
            other => panic!("case 9 payload must be Const(Nat), got {other:?}"),
        },
        other => panic!("case 9 must be ExpectedSort, got {other:?}"),
    }
    // Case 3 (§2 REAL name_eq): the DuplicateLevelParam payload param must
    // decode to the kernel `u` golden; the decl name to `ax.dup`.
    match &jit_results[3] {
        Err(rn::EnvError::DuplicateLevelParam { name, param }) => {
            let (ncomps, nh, _) = unsafe { decode_jit_name(name as *const rn::Name as *const u8) };
            assert_eq!(
                nh, GOLDEN_AX_DUP,
                "case 3: decl-name hash must be the `ax.dup` golden"
            );
            assert_eq!(ncomps, native_from_string_uncached("ax.dup").0);
            let (_, ph, _) = unsafe { decode_jit_name(param as *const rn::Name as *const u8) };
            assert_eq!(
                ph, GOLDEN_U,
                "case 3: the duplicate param must decode to the `u` golden"
            );
        }
        other => panic!("case 3 must be DuplicateLevelParam, got {other:?}"),
    }
    // Case 15 (§2 + Num-part name): the payload NAME carries a LIVE Num
    // component (thm.42) — decoded through the field-reordered Num arm.
    match &jit_results[15] {
        Err(rn::EnvError::DuplicateLevelParam { name, param }) => {
            let (ncomps, nh, _) = unsafe { decode_jit_name(name as *const rn::Name as *const u8) };
            assert_eq!(
                nh, GOLDEN_THM42,
                "case 15: decl-name hash must be the `thm.42` golden"
            );
            assert_eq!(ncomps, vec![Comp::Num(42), Comp::Str(b"thm".to_vec())]);
            let (_, ph, _) = unsafe { decode_jit_name(param as *const rn::Name as *const u8) };
            assert_eq!(ph, GOLDEN_U);
        }
        other => panic!("case 15 must be DuplicateLevelParam, got {other:?}"),
    }
    // Case 14 (§4 inside Const LEVELS): param must decode to `v`.
    match &jit_results[14] {
        Err(rn::EnvError::UndefinedLevelParam { param, .. }) => {
            let (_, ph, _) = unsafe { decode_jit_name(param as *const rn::Name as *const u8) };
            assert_eq!(
                ph, GOLDEN_V,
                "case 14: the undef param found inside Const levels must be `v`"
            );
        }
        other => panic!("case 14 must be UndefinedLevelParam, got {other:?}"),
    }

    // ── NC1 (fail-loud): an always-accept gate must DISAGREE with native on
    //    the wrong-universe definition. ──
    let (native8, _) = native_gate(8);
    assert!(
        native8.is_err(),
        "control: native gate MUST reject the wrong-universe definition"
    );
    let always_accept = |_c: u64| -> Result<(), rn::EnvError> { Ok(()) };
    let bogus = always_accept(8);
    assert_ne!(
        native8.is_ok(),
        bogus.is_ok(),
        "NEGATIVE CONTROL FAILED: an always-accept gate agreed with native on the wrong-universe decl"
    );

    // ── NC2 (fail-loud): deliberately-WRONG universe expectations must be
    //    REJECTED by the structural comparator against the JIT-built sort. ──
    assert!(
        !level_eq_nj(&rn::Level::Zero, &jit5_sort),
        "NEGATIVE CONTROL FAILED: comparator equated IMax(succ u, u) with Zero"
    );
    let swapped_imax = rn::Level::IMax(
        Arc::new(rn::Level::Param(hn1("u"))),
        Arc::new(rn::Level::Succ(Arc::new(rn::Level::Param(hn1("u"))))),
    );
    assert!(
        !level_eq_nj(&swapped_imax, &jit5_sort),
        "NEGATIVE CONTROL FAILED: comparator equated IMax(succ u, u) with the arg-SWAPPED IMax"
    );
    // ── NC2b (fail-loud, crossed REAL name): the same IMax shape built over
    //    `v` instead of `u` must be REJECTED — only the production name walk
    //    distinguishes them. ──
    let crossed_imax = rn::Level::IMax(
        Arc::new(rn::Level::Succ(Arc::new(rn::Level::Param(hn1("v"))))),
        Arc::new(rn::Level::Param(hn1("v"))),
    );
    assert!(
        !level_eq_nj(&crossed_imax, &jit5_sort),
        "NEGATIVE CONTROL FAILED: comparator equated IMax(succ u, u) with IMax(succ v, v)"
    );

    // ── NC3 (fail-loud): a meta-word-corrupted copy of the case-8 payload
    //    must be REJECTED by deep_eq_nj (the bit-identity check reads meta). ──
    let corrupted = rn::Expr {
        kind: j8_exp.kind.clone(),
        meta: rn::ExprMeta(j8_exp.meta.raw() ^ 1),
    };
    assert!(
        !deep_eq_nj(&corrupted, &j8_exp),
        "NEGATIVE CONTROL FAILED: deep_eq_nj accepted a meta-corrupted expr"
    );

    drop(buffer);
}
